<script setup lang="ts">
import { computed } from 'vue'
import { Link, router } from '@inertiajs/vue3'
import { ClipboardCheck, ClipboardList, FileText, Home, LayoutGrid, LogOut, Package, Plus, UserRound } from '@lucide/vue'

interface User { name: string; role: 'admin' | 'operator' | 'viewer' }
interface Summary { total: number; itemTypes: number; completed: number; pending: number }
interface Breakdown { id: number; name: string; total: number }
const props = defineProps<{ user: User; summary: Summary; categoryBreakdown: Breakdown[] }>()
const canManageMaster = computed(() => props.user.role === 'admin')
const navigation = computed(() => [{ label: 'Beranda', href: route('dashboard'), icon: Home, active: true }, { label: 'Serah Terima', href: route('handovers.index'), icon: ClipboardList, active: false }, { label: 'Laporan', href: route('reports.index'), icon: FileText, active: false }, { label: 'Konfirmasi', href: route('handovers.pending'), icon: ClipboardCheck, active: false }, ...(canManageMaster.value ? [{ label: 'Master', href: route('master.index'), icon: LayoutGrid, active: false }] : []), { label: 'Akun', href: route('account.index'), icon: UserRound, active: false }])
function logout(): void { router.post(route('logout')) }
</script>

<template><div class="min-h-screen pb-24"><header class="sticky top-0 z-10 border-b bg-white/90 px-4 py-4 backdrop-blur"><div class="mx-auto flex max-w-3xl items-center justify-between"><div><p class="text-xs font-medium uppercase tracking-wider text-primary">Serah Terima Perusahaan</p><h1 class="text-xl font-bold tracking-tight">SERAYA</h1></div><div class="flex items-center gap-2"><div class="hidden text-right sm:block"><p class="text-sm font-semibold">{{ user.name }}</p><p class="text-xs capitalize text-muted-foreground">{{ user.role }}</p></div><button type="button" class="flex size-10 items-center justify-center rounded-full bg-primary/10 text-primary" title="Keluar" @click="logout"><LogOut class="size-4" /></button></div></div></header><main class="mx-auto flex max-w-3xl flex-col gap-6 px-4 py-6"><section class="rounded-3xl bg-primary p-5 text-primary-foreground shadow-lg shadow-primary/15"><p class="text-sm opacity-80">Selamat datang, {{ user.name }}</p><h2 class="mt-1 text-2xl font-bold">Siap mencatat serah terima hari ini?</h2><Link :href="route('handovers.create')" class="mt-5 inline-flex items-center gap-2 rounded-xl bg-white px-4 py-3 text-sm font-semibold text-primary shadow-sm"><Plus class="size-4" />Buat serah terima</Link></section><section><div class="mb-3 flex items-center justify-between"><h2 class="font-semibold">Ringkasan serah terima</h2><ClipboardList class="size-5 text-muted-foreground" /></div><div class="grid grid-cols-2 gap-3 sm:grid-cols-4"><Link v-for="item in [{ label: 'Total transaksi', value: summary.total, icon: ClipboardList, href: route('handovers.index') }, { label: 'Jenis barang', value: summary.itemTypes, icon: Package, href: route('handovers.index') }, { label: 'Selesai', value: summary.completed, icon: ClipboardCheck, href: route('handovers.index') }, { label: 'Menunggu', value: summary.pending, icon: ClipboardList, href: route('handovers.pending') }]" :key="item.label" :href="item.href" class="rounded-2xl border bg-card p-4 shadow-sm"><component :is="item.icon" class="size-5 text-primary" /><p class="mt-3 text-2xl font-bold">{{ item.value }}</p><p class="text-xs text-muted-foreground">{{ item.label }}</p></Link></div></section><section class="rounded-2xl border bg-card p-5"><div class="flex items-center justify-between"><h2 class="font-semibold">Jenis barang berdasarkan kategori</h2><Link v-if="canManageMaster" :href="route('master.index')" class="text-sm font-semibold text-primary">Kelola master</Link></div><div v-if="categoryBreakdown.length" class="mt-4 space-y-3"><div v-for="category in categoryBreakdown" :key="category.id" class="flex items-center justify-between rounded-xl bg-muted px-3 py-2 text-sm"><span>{{ category.name }}</span><span class="font-semibold">{{ category.total }}</span></div></div><p v-else class="mt-3 text-sm text-muted-foreground">Belum ada jenis barang.</p></section></main><nav class="fixed inset-x-0 bottom-0 z-20 border-t bg-white/95 px-3 py-3 backdrop-blur"><div class="mx-auto flex max-w-3xl items-center justify-around"><Link v-for="item in navigation" :key="item.label" :href="item.href" class="flex flex-col items-center gap-1 rounded-xl px-3 py-2 text-xs" :class="item.active ? 'text-primary' : 'text-muted-foreground'"><component :is="item.icon" class="size-5" /><span>{{ item.label }}</span></Link></div></nav></div></template>
